// Scanner state: which bracket we are inside, so `**` can be told apart —
// `f(**kw)` is fine and MicroPython supports it, `{**d}` is not.
#define PYGRAM_SYNTAX_DEPTH 24

static inline bool pygram_word_at(const char *s, const char *p, const char *word) {
    size_t n = strlen(word);
    if (strncmp(p, word, n) != 0) {
        return false;
    }
