// Is `p` at the start of a logical line (only whitespace before it)?
static inline bool pygram_line_start(const char *s, const char *p) {
    while (p > s) {
        char c = *--p;
        if (c == '\n') {
            return true;
        }
        if (c != ' ' && c != '\t') {
            return false;
        }
    }
