        if (*p == '#') {
            break;
        }
        if (*p == '\'' || *p == '"') {
            in_s = true;
            q = *p;
            last = *p;
            continue;
        }
        if (*p != ' ' && *p != '\t' && *p != '\r') {
            last = *p;
        }
    }
    return last == ':';
}

