    // 'e' always writes one digit before the point, so the exponent it reports
    // is unambiguous, and the NOTATION is then chosen deliberately by CPython's
    // rule rather than inherited from a formatter's own.
    char buf[48];
    int len = 0;
    int prec = 1;
    for (; prec <= 17; prec++) {
        len = mp_format_float(o_val, buf, sizeof(buf), 'e', prec - 1, '\\0');
        if (len <= 0) {
            break;
        }
        mp_obj_t back = mp_parse_num_float(buf, (size_t)len, false, NULL);
        if (mp_obj_is_float(back) && mp_obj_float_get(back) == o_val) {
            break;
        }
    }
    // nan and inf have no exponent to read; they fall through to the printer
    // below, which already spells them the way CPython does.
    const char *epos = NULL;
    for (int i = 0; i < len; i++) {
        if (buf[i] == 'e') {
            epos = buf + i;
            break;
        }
    }
    if (len > 0 && epos != NULL) {
        int exp = (int)strtol(epos + 1, NULL, 10);
        // CPython's repr style (Python/pystrtod.c, format_float_short with
        // mode 'r'): exponential when decpt <= -4 or decpt > 16, where decpt is
        // the position of the decimal point, one more than this exponent.
        // Verified against CPython 3.11 over 299,851 random doubles.
        int decpt = exp + 1;
        if (decpt <= -4 || decpt > 16) {
            // Already exactly the form CPython writes, two exponent digits and
            // all: 1e+22, 1e-05, 5e-324.
            mp_print_strn(print, buf, (size_t)len, 0, '\\0', 0);
            return;
        }
        // Fixed notation with exactly the decimals these digits need, so no
        // trailing zeros are invented and none are lost. 'f' is used rather
        // than 'g' for the same reason the search is: %g would re-decide the
        // notation and strip digits on its own terms.
        int dec = prec - 1 - exp;
        if (dec < 0) {
            dec = 0;
        }
        len = mp_format_float(o_val, buf, sizeof(buf), 'f', dec, '\\0');
        if (len > 0) {
            bool has_point = false;
            for (int i = 0; i < len; i++) {
                if (buf[i] == '.') {
                    has_point = true;
                    break;
                }
            }
            mp_print_strn(print, buf, (size_t)len, 0, '\\0', 0);
            if (!has_point) {
                // 'f' with zero decimals drops the point; CPython's repr keeps
                // it (25.0, not 25).
                mp_print_str(print, ".0");
            }
            return;
        }
    }
'''
